import "server-only";
import type { Firestore } from "firebase-admin/firestore";
import { getAdminFirestore } from "@/shared/lib/firebase/admin";
import { AUDIT_COLLECTION } from "@/shared/lib/firebase/collections";
import { logServerError } from "@/shared/lib/log";
import { err, ok, type Result } from "@/shared/lib/result";
import type { AuditEntry, AuditLog } from "../../domain/ports";
import { teamError, type TeamError } from "../../domain/team-error";

/** Append-only: entries are only ever added, with an id generated by Firestore. No client can read or write them. */
export class FirestoreAuditLog implements AuditLog {
  constructor(private readonly getDb: () => Firestore = getAdminFirestore) {}

  async append(entry: AuditEntry): Promise<Result<void, TeamError>> {
    try {
      await this.getDb().collection(AUDIT_COLLECTION).add(entry);
      return ok(undefined);
    } catch (cause) {
      logServerError("admin.audit.append", cause);
      return err(teamError("unknown"));
    }
  }
}
